<div class="section-heading"><div><span>Partner assistance</span><h2>Help &amp; Support</h2><p>Choose a topic and send a secure message directly to the Udyam operations team.</p></div></div>
<div class="support-grid"><section class="portal-card support-form-card"><div class="card-heading"><div><span>New request</span><h3>How can we help?</h3></div><i data-lucide="headset"></i></div><form method="post" action="<?= htmlspecialchars(url('/customer/support')) ?>" class="portal-form"><?= csrf_field() ?><label>Topic<select name="topic" required><option value="general">General support</option><option value="subscription">Subscription or renewal</option><option value="billing">Billing, invoice or payment</option><option value="application">Service application</option><option value="document">Document upload</option><option value="technical">Technical assistance</option></select></label><label>Subject<input name="subject" maxlength="255" required placeholder="A short summary of your query"></label><label>Message<textarea name="message" maxlength="5000" required placeholder="Include any useful details so our team can help you faster."></textarea></label><button class="primary-action" type="submit"><i data-lucide="send"></i> Send to Udyam Support</button></form></section><section class="portal-card support-guidance"><span class="support-guidance-icon"><i data-lucide="messages-square"></i></span><h3>We are here to help</h3><p>Use this secure channel for your account, membership, service, document, invoice and payment questions.</p><ul><li><i data-lucide="clock-3"></i>Track requests from this page</li><li><i data-lucide="bell-ring"></i>Receive updates in Notifications</li><li><i data-lucide="shield-check"></i>Your partner data stays protected</li></ul></section></div>
<section class="portal-card support-history"><div class="card-heading"><div><span>Conversation history</span><h3>My support requests</h3></div></div><?php if(!$tickets): ?><div class="empty">You have not sent a support request yet.</div><?php else: ?><div class="portal-list"><?php foreach($tickets as $ticket): ?><div><i data-lucide="message-circle-question"></i><span><strong><?= htmlspecialchars((string)$ticket['subject']) ?></strong><small><?= htmlspecialchars(ucfirst((string)$ticket['topic'])) ?> · <?= htmlspecialchars(date('d M Y',strtotime((string)$ticket['created_at']))) ?><?= !empty($ticket['admin_reply']) ? ' · Reply received' : '' ?></small><?php if(!empty($ticket['admin_reply'])): ?><em><?= htmlspecialchars((string)$ticket['admin_reply']) ?></em><?php endif; ?></span><b class="subscription-status <?= htmlspecialchars((string)$ticket['status']) ?>"><?= htmlspecialchars(ucfirst(str_replace('_',' ',(string)$ticket['status']))) ?></b></div><?php endforeach; ?></div><?php endif; ?></section>
